using Arconist.Core;
using System.Text.Json;

string root=args.Length>0?args[0]:".",evidence=args.Length>1?args[1]:"arctap-evidence";Directory.CreateDirectory(evidence);
int passed=0,failed=0;var outcomes=new List<object>();
void Check(bool ok,string message){if(!ok)throw new Exception(message);}
void Test(string name,Action body){try{body();passed++;outcomes.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}catch(Exception e){failed++;outcomes.Add(new{name,status="FAIL",error=e.ToString()});Console.WriteLine("FAIL "+name+": "+e.Message);}}
string Load(string name)=>File.ReadAllText(Path.Combine(root,"reconstructed/godot/content",name));
string Aff(string body)=>"AudioOffset:0\nTimingPointDensityFactor:1.0\n-\ntiming(0,120.00,4.00);\n"+body;
const string body="arc(1000,2000,0.50,0.50,s,0.50,0.50,0,none,true)[arctap(1500)];";
Kernel New(string? text=null,int height=500){var k=new Kernel(Chart.Parse(text??Load("native_arc_tap.aff")),arcHeight:height);k.Frame(0);k.Frame(3002);return k;}
void F(Kernel k,int e)=>k.Frame(e+3002);
SkyContact At(ArcTapState c)=>new(c.InputTarget);
Test("exact E025 native fixture bytes preserved",()=>Check(File.ReadAllBytes(Path.Combine(root,"research_harness/fixtures/native_arc_tap.aff")).SequenceEqual(File.ReadAllBytes(Path.Combine(root,"reconstructed/godot/content/native_arc_tap.aff"))),"fixture bytes"));
Test("typed parsed parent child relationship and retained metadata",()=>{var chart=Chart.Parse(Load("native_arc_tap.aff"));var p=chart.Arcs.Single();var c=p.Children.Single();Check(ReferenceEquals(c.Parent,p)&&c.ParentId==p.Id&&c.Time==1500&&p.Start==1000&&p.End==2000&&p.X0==.5f&&p.X1==.5f&&p.Y0==.5f&&p.Y1==.5f&&p.Curve=="s"&&p.Color==0&&p.Effect=="none"&&p.Trace&&p.Mode==1&&p.Bpm==120&&p.Density==1&&p.SourceOrder==0,"typed identity/provenance");});
Test("child alone contributes N1 and parent end2500",()=>{var chart=Chart.Parse(Load("native_arc_tap.aff"));Check(chart.JudgmentUnits==1&&chart.EndTime==2500&&chart.Taps.Count==0&&chart.Arcs[0].Checkpoints.Count==0,"no artificial parent checkpoint/head/tail/ground duplicate");});
Test("runtime child links exact parent and is not independently indexed tap",()=>{var k=New();var c=k.ArcTaps.Single();Check(ReferenceEquals(c,k.Arcs[0].Children.Single())&&ReferenceEquals(c.Parent,k.Arcs[0])&&ReferenceEquals(c.Data.Parent,k.Chart.Arcs[0])&&c.Id!=c.Parent.Id&&k.Notes.Count==0&&c.Active,"runtime identity/range via parent");});
Test("E025 local geometry H0 separate from Godot H500",()=>{var c=New(height:0).ArcTaps.Single();Check(c.Local.X==0&&c.Local.Y==50&&c.Local.Z==-4044.5f&&c.InputTarget.Z==0&&c.Parent.Geometry.Z==-8089,"native geometry");Check(New().ArcTaps.Single().Local.Y==300,"declared playable height");});
Test("linear child geometry uses own normalized time and parent translation",()=>{var k=New(Aff(body.Replace("0.50,0.50,s,0.50,0.50","0.20,0.80,s,0.25,0.75")));var c=k.ArcTaps[0];Check(c.Local.X==255&&c.InputTarget.X==0&&c.Local.Y==300&&c.Local.Z==-4044.5f,"linear evaluator/parent X");F(k,1500);Check(c.WorldPosition.Z==c.Parent.Depth+c.Local.Z&&c.InputTarget.Z==0,"render depth versus input plane");});
Test("E025 first eligible DOWN then fresh duplicate consumed guard",()=>{
 var k=New(height:0);var c=k.ArcTaps.Single();F(k,1500);var trace=new List<object>();string? first=null;int records=0;
 using var reference=JsonDocument.Parse(File.ReadAllText(Path.Combine(root,"reference_traces/r008/native-arctap.json")));var expected=reference.RootElement.GetProperty("rows").EnumerateArray().ToArray();
 void Row(int index,string phase){var r=expected[index];trace.Add(new{phase,consumed=c.Consumed,k.Pure,k.Shining,k.Far,k.Lost,k.Score,health=(double)k.Health,recorderCalls=records,contacts=k.Contacts.Select(t=>new{t.Pointer,t.Id}),candidates=k.Candidates.ToArray(),classification=k.Classifications.ToArray()});Check(c.Consumed==r.GetProperty("consumed").GetBoolean()&&k.Pure==r.GetProperty("pure").GetInt32()&&k.Shining==r.GetProperty("shining").GetInt32()&&k.Far==0&&k.Lost==0&&k.Score==r.GetProperty("score").GetInt32()&&(double)k.Health==r.GetProperty("health").GetDouble()&&records==r.GetProperty("recorderCalls").GetInt32(),phase+" first differing recorder/child state");}
 try{Row(0,"before");Check(ArcTapSpatial.Matches(c.InputTarget.X,c.InputTarget.Y,At(c)),"first spatial");k.DownSpatial(4502,42,0,At(c));records+=k.Judgments.Count;Check(k.Contacts.Single().Id==0&&k.Candidates.SequenceEqual(new[]{c.Id})&&k.Classifications.Single().Outcome=="SHINING_PURE","first traversal/classifier");Row(1,"first");k.Up(42);
 Check(ArcTapSpatial.Matches(c.InputTarget.X,c.InputTarget.Y,At(c)),"second spatial");k.DownSpatial(4502,43,0,At(c));records+=k.Judgments.Count;Check(k.Contacts.Single().Id==1&&k.Candidates.SequenceEqual(new[]{c.Id})&&k.Classifications.Single().Outcome=="guard_consumed"&&!k.Classifications.Single().ConsumesInput,"second fresh pointer reaches consumed guard");Row(2,"duplicate");k.Up(43);Check(k.ContactCount==0&&k.Result==null&&c.Parent.Color.Owner==-1&&k.ClaimedIds.Count==0,"cleanup/no native result or parent owner claim");}
 catch(Exception e){first=e.Message;throw;}
 finally{File.WriteAllText(Path.Combine(evidence,"E025-parent-child.json"),JsonSerializer.Serialize(new{authority="E025",firstDifference=first,trace,nativeCompletion=false},new JsonSerializerOptions{WriteIndented=true}));}
});
Test("DOWN classifies without running frame geometry or expiry",()=>{var k=New();F(k,1490);var c=k.ArcTaps[0];var before=c.WorldPosition;k.DownSpatial(4502,42,0,At(c));Check(k.LastFrameTime==1490&&k.Timeline.EffectiveTime==1500&&c.WorldPosition.Z==before.Z&&c.Consumed,"input ordering");});
Test("held contact MOVE FRAME never substitutes for initial DOWN",()=>{var k=New();var c=k.ArcTaps[0];F(k,1000);k.DownSpatial(4002,42,0,At(c));Check(k.Classifications.Single().Outcome=="outside_window","early legitimate DOWN");F(k,1500);k.MoveSpatial(42,0,At(c));F(k,1500);Check(k.Pure==0&&!c.Consumed&&k.ContactCount==1&&c.Parent.Records.Count==0&&!c.Parent.Holding&&c.Parent.Color.Owner==-1,"no continuous award");F(k,1601);Check(k.Lost==1&&c.Missed,"expiry");});
Test("ground keyboard contacts cannot select sky children",()=>{var k=New();F(k,1500);foreach(int lane in new[]{2,3,4,5}){k.Down(4502,lane,lane);k.Up(lane);}Check(k.Pure==0&&!k.ArcTaps[0].Consumed&&k.Candidates.Count==0,"no fabricated sky");});
Test("spatial miss retains unconsumed child and permits fresh valid click",()=>{var k=New();F(k,1500);var c=k.ArcTaps[0];k.DownSpatial(4502,42,0,new SkyContact(new SkyPoint(9000,300,0)));Check(k.Pure==0&&!c.Consumed&&k.Candidates.Count==0,"spatial miss");k.Up(42);k.DownSpatial(4502,43,0,At(c));Check(k.Pure==1&&c.Consumed&&c.Contact==1,"fresh valid click");});
Test("arc-tap strict extent302 differs from ordinary190",()=>{SkyContact P(float x)=>new(new SkyPoint(x,300,0));Check(ArcTapSpatial.Matches(0,300,P(301.99f))&&!ArcTapSpatial.Matches(0,300,P(302))&&!ArcTapSpatial.Matches(0,300,P(-302)),"strict302");Check(ArcTapSpatial.Matches(0,300,P(250))&&!ArcSpatial.Matches(0,300,P(250)),"distinct flags");});
Test("arc-tap lower margin Y clamp and integer truncation",()=>{SkyContact P(float y)=>new(new SkyPoint(0,y,0));Check(!ArcTapSpatial.Matches(0,500,P(190.999f))&&ArcTapSpatial.Matches(0,500,P(191)),"lower margin/truncation");Check(ArcTapSpatial.Matches(0,100,P(349.999f))&&!ArcTapSpatial.Matches(0,100,P(350)),"upper strict edge");Check(ArcTapSpatial.Matches(0,300,P(-200))&&!ArcTapSpatial.Matches(0,300,P(900)),"clamp100..550");});
Test("camera frame scale depth and invalid positions",()=>{SkyContact P(float x,float z=0,float cam=900,float height=720)=>new(new SkyPoint(x,300,z),cam,height);Check(ArcTapSpatial.Matches(0,300,P(339.74f,cam:900,height:960))&&!ArcTapSpatial.Matches(0,300,P(339.75f,cam:900,height:960)),"scaled strict edge");Check(!ArcTapSpatial.Matches(0,300,P(0,-1000))&&ArcTapSpatial.Matches(0,300,P(0,-999.99f)),"depth");Check(!ArcTapSpatial.Matches(0,300,P(float.NaN))&&!ArcTapSpatial.Matches(0,300,P(0,height:0))&&!ArcTapSpatial.Matches(float.NaN,300,P(0)),"invalid");});
foreach(int error in new[]{-121,-120,-101,-100,-51,-50,-26,-25,0,25,26,50,51,100,101,120,121}){int delta=error;Test("E002 tap-tier child error "+delta,()=>{var k=New();var c=k.ArcTaps[0];int e=1500+delta;k.DownSpatial(e+3002,42,0,At(c));int absolute=Math.Abs(delta);string want=absolute<=25?"SHINING_PURE":absolute<=50?"PURE":absolute<=100?"FAR":absolute<=120?"LOST":"outside_window";Check(k.Classifications.Single().Outcome==want&&k.Classifications.Single().ConsumesInput==(absolute<=120),"classification");Check(c.Consumed==(absolute<=100)&&c.Missed==(absolute>100&&absolute<=120),"child outcome");if(absolute<=100){Check(k.Score==(absolute<=25?10000001:absolute<=50?10000000:5000000),"tier score");Check((double)k.Health==(absolute<=50?80.19999694824219:40.099998474121094),"E006 per-tier float32 gain");}if(absolute<=25)Check(k.Early==0&&k.Late==0,"shining side");else if(absolute<=100)Check(k.Early==(delta<0?1:0)&&k.Late==(delta>0?1:0),"early/late");});}
Test("child strict expiry1600/1601 and completed LOST",()=>{var k=New();F(k,1600);Check(k.Lost==0&&!k.ArcTaps[0].Missed,"equality");F(k,1601);Check(k.Lost==1&&k.ArcTaps[0].Missed&&k.Pure==0,"expiry");F(k,1601);Check(k.Lost==1&&k.Judgments.Count==0,"miss guard");F(k,2501);Check(k.Result!.Lost==1&&k.Result.RecordedLost==1&&k.Result.Pure==0&&k.Result.Score==0,"result reconciliation");var mixed=New(Load("arctap_practice.aff"));foreach(var tap in mixed.Chart.Taps.Take(2)){F(mixed,tap.Time);mixed.Down(tap.Time+3002,200+tap.Ordinal,tap.Lane);mixed.Up(200+tap.Ordinal);}F(mixed,6100);float before=mixed.Health;Check(mixed.Combo==2,"pre-miss combo");F(mixed,6101);Check(mixed.Lost==1&&mixed.Health==before-2f&&mixed.Combo==0,"derived ArcTap miss damage/recorder reset");});
Test("late DOWN input-first versus frame-first child guards",()=>{var a=New();var b=New();F(a,1500);F(b,1500);a.DownSpatial(4612,42,0,At(a.ArcTaps[0]));F(b,1610);b.DownSpatial(4612,42,0,At(b.ArcTaps[0]));Check(a.Classifications.Single().Outcome=="LOST"&&a.Classifications.Single().ConsumesInput&&b.Classifications.Single().Outcome=="guard_missed"&&!b.Classifications.Single().ConsumesInput&&a.Lost==1&&b.Lost==1,"E035 ordering applies within trace parent");});
Test("repeated frames do not duplicate accepted or missed units",()=>{var k=New();F(k,1500);k.DownSpatial(4502,42,0,At(k.ArcTaps[0]));for(int i=0;i<30;i++)F(k,1500);F(k,2001);Check(k.Pure==1&&k.Shining==1&&k.Lost==0&&k.Combo==1&&k.Judgments.Count==0,"resolved guard");});
Test("completed reconstructed E025 chart uses existing results",()=>{var k=New();F(k,1500);k.DownSpatial(4502,42,0,At(k.ArcTaps[0]));k.Up(42);F(k,2501);var r=k.Result!;Check(r.Pure==1&&r.Shining==1&&r.Lost==0&&r.Score==10000001&&r.Health==80&&r.Category==3&&r.MaxCombo==1,"reconstructed result; not native E025 completion");});
Test("mixed noncompeting chart N5 results and event order",()=>{var k=New(Load("arctap_practice.aff"));Check(k.Chart.JudgmentUnits==5&&k.Chart.EndTime==10620,"mixed construction");var judged=new List<string>();for(int e=1;e<=10621;e++){F(k,e);foreach(var t in k.Chart.Taps.Where(t=>t.Time==e)){k.Down(e+3002,100+t.Ordinal,t.Lane);judged.AddRange(k.Judgments.Select(j=>j.Note));k.Up(100+t.Ordinal);}if(e==6000){k.DownSpatial(e+3002,42,0,At(k.ArcTaps[0]));judged.AddRange(k.Judgments.Select(j=>j.Note));k.Up(42);}}Check(k.Result!.Score==10000005&&k.Pure==5&&k.MaxCombo==5&&k.Lost==0&&judged.Count==5&&judged[2]==k.ArcTaps[0].Id,"mixed full path");});
Test("60second pause freezes child and resumes fresh click",()=>{var k=New();F(k,1400);var c=k.ArcTaps[0];var before=c.WorldPosition;k.Pause(4402);k.Frame(64402);Check(k.Timeline.EffectiveTime==1400&&!c.Consumed&&!c.Missed&&c.WorldPosition.Z==before.Z&&k.Pure==0,"frozen");k.DownSpatial(64402,42,0,At(c));Check(k.ContactCount==0,"paused input rejected");k.Resume(64402);k.Frame(64502);Check(!c.Consumed&&k.Pure==0,"resume alone no award");k.DownSpatial(64502,43,0,At(c));Check(k.Pure==1&&c.Contact==0,"normal fresh click after resume");});
Test("retained pre-pause contact does not autojudge on resume",()=>{var k=New();var c=k.ArcTaps[0];F(k,1000);k.DownSpatial(4002,42,0,At(c));k.Pause(4402);k.Frame(64402);k.Resume(64402);k.Frame(64502);Check(k.ContactCount==1&&!c.Consumed&&k.Pure==0,"retained is not DOWN");k.Up(42);k.DownSpatial(64502,43,0,At(c));Check(c.Consumed&&c.Contact==1,"new DOWN judges");});
Test("paused UP and CANCEL clean distinct contacts without child mutation",()=>{var k=New();F(k,1000);var c=k.ArcTaps[0];k.DownSpatial(4002,42,0,At(c));k.DownSpatial(4002,43,0,At(c));k.Pause(4402);k.Up(42);k.Cancel(43);Check(k.ContactCount==0&&!c.Terminal&&k.Pure==0&&k.ClaimedIds.Count==0,"cleanup");});
Test("100 independent sessions reset consumption and contact IDs",()=>{for(int i=0;i<100;i++){var k=New();F(k,1500);var c=k.ArcTaps[0];Check(!c.Consumed&&c.Contact==-1,"fresh child");k.DownSpatial(4502,42,0,At(c));Check(k.Pure==1&&c.Contact==0,"new independent award");}});
Test("unsupported child lists modes domains and conflicts reject",()=>{var rejected=new[]{body.Replace("true","false"),body.Replace("[arctap(1500)]",""),body.Replace("arctap(1500)","arctap(1500),arctap(1600)"),body.Replace("[arctap(1500)]","[arctap(1500)][arctap(1600)]"),body.Replace("arctap(1500)","arctap(1000)"),body.Replace("arctap(1500)","arctap(2000)"),body.Replace("arctap(1500)","arctap(1500.0)"),body.Replace("arctap(1500)","arctap(-1)"),body.Replace(",s,",",b,"),body.Replace(",0,none",",1,none"),body.Replace("none","effect"),body+"(1500,3);",body+"hold(1200,1800,3);"};foreach(var input in rejected){bool no=false;try{Chart.Parse(Aff(input));}catch(Exception e)when(e is FormatException||e is NotSupportedException){no=true;}Check(no,input);}});
File.WriteAllText(Path.Combine(evidence,"arctap-core-tests.json"),JsonSerializer.Serialize(new{passed,failed,skipped=0,outcomes},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"R008 core: {passed+failed}; passed:{passed}; failed:{failed}; skipped:0");return failed==0?0:1;
